export default function SearchNationImage() {

    return (
        <>
            {/* 헤드 베너*/}
            <div class="SNIeventBennerContainer">
                <img src="https://i.namu.wiki/i/nBpX15C4ejIewZ1iuTWMPIdK6i05TmG86_6kcxRqqL3bZ4hu7C8CmBA7RSV2V3XyZiXEYZegG45OBFPbYrJrgQ.webp" alt=""></img>
                <div class="SNIopacityBox"></div>
                <div class="SNIbennerTextCon">
                    <p class="SNIbennerTextT">{"서울"}</p>
                    <p class="SNIbennerTextB">{"South Korea, Seoul, Gwanghwamun"}</p> {/* 여기 글자 너무 구림 혼자 독보적 블랙이라 그런것 같은데 어떻게 바꿔야될지 모르겠음 색 바꾸면 너무 흐리게 보임 그렇다고 색 바꾸고 굵기를 늘리자니 다채롭게 구림 역시 디자인을 전공했어야*/}
                </div>
            </div>
        </>
    )
}
